-- apkdepot.sql: skema database MOD (8 tabel)
-- Impor: sudo mariadb < apkdepot.sql
CREATE DATABASE IF NOT EXISTS apkdepot CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE apkdepot;
CREATE TABLE pengguna ( id CHAR(36) NOT NULL, nama_pengguna VARCHAR(50) NOT NULL, kata_sandi_hash VARCHAR(255) NOT NULL, nama_pengelola VARCHAR(100) NOT NULL, dibuat_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY uq_pengguna_nama (nama_pengguna) )
ENGINE=InnoDB;
CREATE TABLE depot ( id CHAR(36) NOT NULL, id_pengguna CHAR(36) NOT NULL, nama_depot VARCHAR(100) NOT NULL, alamat TEXT NOT NULL, jam_buka TIME NOT NULL, jam_tutup TIME NOT NULL, notifikasi_stok_menipis TINYINT(1) NOT NULL DEFAULT 1, notifikasi_sparepart TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (id), CONSTRAINT fk_depot_pengguna FOREIGN KEY (id_pengguna) REFERENCES pengguna (id) )
ENGINE=InnoDB;
CREATE TABLE produk ( id CHAR(36) NOT NULL, id_depot CHAR(36) NOT NULL, nama_produk VARCHAR(100) NOT NULL, jenis ENUM('jenis_air','galon_kosong','galon_kosong_isi','es','sparepart') NOT NULL, harga DECIMAL(12,2) NULL DEFAULT NULL, masa_pakai_hari INT NULL DEFAULT NULL, terakhir_diganti DATE NULL DEFAULT NULL, ambang_stok_minimum INT NULL DEFAULT NULL, aktif TINYINT(1) NOT NULL DEFAULT 1, dibuat_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, diperbarui_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY uq_produk_depot_jenis_nama (id_depot, jenis, nama_produk), CONSTRAINT fk_produk_depot FOREIGN KEY (id_depot) REFERENCES depot (id) )
ENGINE=InnoDB;
CREATE TABLE stok ( id CHAR(36) NOT NULL, id_produk CHAR(36) NOT NULL, jumlah_saat_ini INT NOT NULL DEFAULT 0, diperbarui_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY uq_stok_produk (id_produk), CONSTRAINT fk_stok_produk FOREIGN KEY (id_produk) REFERENCES produk (id) )
ENGINE=InnoDB;
CREATE TABLE peminjam ( id CHAR(36) NOT NULL, id_depot CHAR(36) NOT NULL, nama VARCHAR(100) NOT NULL, alamat TEXT NOT NULL, jumlah_galon_dipinjam INT NOT NULL DEFAULT 0, dibuat_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, diperbarui_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (id), CONSTRAINT fk_peminjam_depot FOREIGN KEY (id_depot) REFERENCES depot (id) )
ENGINE=InnoDB;
CREATE TABLE transaksi ( id CHAR(36) NOT NULL, id_depot CHAR(36) NOT NULL, jenis_aksi ENUM('isi_ulang','beli_galon_kosong','galon_kosong_isi','beli_es', 'pinjam_galon_isi','catat_pengeluaran','pendapatan_lain', 'ganti_sparepart','kembalikan_galon') NOT NULL, id_produk CHAR(36) NULL DEFAULT NULL, id_peminjam CHAR(36) NULL DEFAULT NULL, deskripsi VARCHAR(255) NULL DEFAULT NULL, jumlah INT NOT NULL DEFAULT 1, harga_satuan DECIMAL(12,2) NULL DEFAULT NULL, total DECIMAL(14,2) NOT NULL DEFAULT 0, tipe_arus_kas ENUM('pemasukan','pengeluaran') NOT NULL, status ENUM('aktif','dibatalkan') NOT NULL DEFAULT 'aktif', dibatalkan_pada TIMESTAMP NULL DEFAULT NULL, alasan_batal TEXT NULL DEFAULT NULL, catatan TEXT NULL DEFAULT NULL, dibuat_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), KEY idx_transaksi_depot_tanggal (id_depot, dibuat_pada), CONSTRAINT fk_transaksi_depot FOREIGN KEY (id_depot) REFERENCES depot (id), CONSTRAINT fk_transaksi_produk FOREIGN KEY (id_produk) REFERENCES produk (id), CONSTRAINT fk_transaksi_peminjam FOREIGN KEY (id_peminjam) REFERENCES peminjam (id) )
ENGINE=InnoDB;
CREATE TABLE pergerakan_stok ( id CHAR(36) NOT NULL, id_produk CHAR(36) NOT NULL, id_transaksi CHAR(36) NULL DEFAULT NULL, perubahan INT NOT NULL, jenis_pergerakan ENUM('otomatis','koreksi_manual') NOT NULL, keterangan TEXT NULL DEFAULT NULL, dibuat_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), CONSTRAINT fk_pergerakan_produk FOREIGN KEY (id_produk) REFERENCES produk (id), CONSTRAINT fk_pergerakan_transaksi FOREIGN KEY (id_transaksi) REFERENCES transaksi (id) )
ENGINE=InnoDB;
CREATE TABLE pengingat ( id CHAR(36) NOT NULL, id_depot CHAR(36) NOT NULL, jenis ENUM('stok_menipis','sparepart_jatuh_tempo') NOT NULL, id_produk CHAR(36) NOT NULL, pesan TEXT NOT NULL, status ENUM('belum_dibaca','dibaca','selesai') NOT NULL DEFAULT 'belum_dibaca', dibuat_pada TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), CONSTRAINT fk_pengingat_depot FOREIGN KEY (id_depot) REFERENCES depot (id), CONSTRAINT fk_pengingat_produk FOREIGN KEY (id_produk) REFERENCES produk (id) )
ENGINE=InnoDB;
